pub(super) fn exclusion(
    cli: &Cli,
    cli_kv_overrides: &[(String, toml::Value)],
    loader_overrides: &LoaderOverrides,
    workload_identity_selected: bool,
    exec_server_url: Option<&std::ffi::OsStr>,
) -> Option<&'static str> {
    if cli.no_daemon {
        Some("--no-daemon")
    } else if cli.oss {
        Some("--oss")
    } else if workload_identity_selected {
        Some("workload identity")
    } else if exec_server_url.is_some() {
        Some("executor selection (CODEX_EXEC_SERVER_URL)")
    } else if cli.agents_overview {
        None
    } else if cli.config_profile_v2.is_some() {
        Some("--profile")
    } else {
        config_exclusion(
            cli_kv_overrides,
            loader_overrides,
            cli.strict_config,
            cli.bypass_hook_trust,
        )
    }
}

pub(super) fn config_exclusion(
    cli_kv_overrides: &[(String, toml::Value)],
    loader_overrides: &LoaderOverrides,
    strict_config: bool,
    bypass_hook_trust: bool,
) -> Option<&'static str> {
    if !cli_kv_overrides
        .iter()
        .all(|(key, value)| match key.as_str() {
            "suppress_unstable_features_warning" | "tui.fullscreen_transcript" => value.is_bool(),
            "tui" => value.as_table().is_some_and(|tui| {
                tui.len() == 1
                    && tui
                        .get("fullscreen_transcript")
                        .is_some_and(toml::Value::is_bool)
            }),
            "features" => value.as_table().is_some_and(|features| {
                !features.is_empty()
                    && features
                        .iter()
                        .all(|(name, value)| allowed_feature(name) && value.is_bool())
            }),
            _ => key.strip_prefix("features.").is_some_and(allowed_feature) && value.is_bool(),
        })
    {
        Some("command-line configuration overrides (-c, --enable, --disable, or --search)")
    } else if !loader_overrides_are_default(loader_overrides) {
        Some("custom configuration loader")
    } else if strict_config {
        Some("--strict-config")
    } else if bypass_hook_trust {
        Some("--dangerously-bypass-hook-trust")
    } else {
        None
    }

if auto_start_daemon && daemon_exclusion.is_none() {
    let output = startup_draft
        .run_until(async {
            // Daemon startup needs no terminal input. Keep the composer visible and
            // responsive while it checks the running server or prepares an installation.
            let result = codex_app_server_daemon::start_with_features(&daemon_features).await;
            daemon_telemetry::record_start(&config, &result).await;
            match result {
                Ok(output) => Ok(Some(output)),
                #[cfg(windows)]
                Err(err) if err.is::<codex_app_server_daemon::DetachedLaunchRestricted>() => {
                    Ok(None)
                }
                Err(err) => Err(std::io::Error::other(format!(
                    "{err:#}\n{}",
                    daemon_startup::FAILURE_HINT
                ))),
            }
        })
        .await??;
    if let Some(output) = output {
        managed_daemon = output.backend.is_some();
        app_server_target = AppServerTarget::LocalDaemon {
            endpoint: RemoteAppServerEndpoint::UnixSocket {
                socket_path: AbsolutePathBuf::from_absolute_path_checked(output.socket_path)?,
            },
            allow_embedded_fallback: false,
        };
    } else {
        app_server_target = AppServerTarget::Embedded;
        daemon_exclusion = Some("this Windows launcher");
    }
}

pub fn resolve_remote_addr(addr: &str) -> color_eyre::Result<RemoteAppServerEndpoint> {
    if let Some(socket_path) = addr.strip_prefix("unix://") {
        let socket_path = if socket_path.is_empty() {
            let codex_home = find_codex_home().wrap_err("failed to resolve CODEX_HOME")?;
            codex_app_server_client::app_server_control_socket_path(&codex_home)
                .map_err(color_eyre::Report::new)?
        } else {
            AbsolutePathBuf::relative_to_current_dir(socket_path)
                .map_err(color_eyre::Report::new)?
        };
        return Ok(RemoteAppServerEndpoint::UnixSocket { socket_path });

fn app_server_target_for_launch(
    explicit_remote_endpoint: Option<RemoteAppServerEndpoint>,
    default_daemon_socket: Option<AbsolutePathBuf>,
    can_reuse_implicit_local_daemon: bool,
    workload_identity_selected: bool,
    exec_server_url: Option<&std::ffi::OsStr>,
) -> std::io::Result<AppServerTarget> {
    if workload_identity_selected {
        if explicit_remote_endpoint.is_some() {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidInput,
                "workload identity must be configured on the remote app-server host",
            ));
        }
        return Ok(AppServerTarget::Embedded);
    }
    Ok(match explicit_remote_endpoint {
        Some(endpoint) => AppServerTarget::Remote { endpoint },
        // A shared daemon cannot adopt this invocation's executor selection.
        None if can_reuse_implicit_local_daemon && exec_server_url.is_none() => {
            default_daemon_socket.map_or(AppServerTarget::Embedded, |socket_path| {
                AppServerTarget::LocalDaemon {
                    allow_embedded_fallback: true,
                    endpoint: RemoteAppServerEndpoint::UnixSocket { socket_path },
                }
            })
        }
        None => AppServerTarget::Embedded,
    })

const APP_SERVER_CONTROL_SOCKET_DIR_NAME: &str = "app-server-control";
const APP_SERVER_CONTROL_SOCKET_FILE_NAME: &str = "app-server-control.sock";
const APP_SERVER_STARTUP_LOCK_FILE_NAME: &str = "app-server-startup.lock";
const DAEMON_RECOVERY_FILE_NAME: &str = "loaded-threads.json";

pub fn daemon_recovery_file_path(codex_home: &Path) -> PathBuf {
    codex_home
        .join("app-server-daemon")
        .join(DAEMON_RECOVERY_FILE_NAME)
}

pub fn app_server_control_socket_path(codex_home: &Path) -> std::io::Result<AbsolutePathBuf> {
    AbsolutePathBuf::from_absolute_path(
        codex_home
            .join(APP_SERVER_CONTROL_SOCKET_DIR_NAME)
            .join(APP_SERVER_CONTROL_SOCKET_FILE_NAME),
    )

pub(crate) async fn replay_requests_to_connection_for_thread(
    &self,
    connection_id: ConnectionId,
    thread_id: ThreadId,
) {
    let requests = self.pending_requests_for_thread(thread_id).await;
    for request in requests {
        if let Err(err) = self
            .sender
            .send(OutgoingEnvelope::ToConnection {
                connection_id,
                message: OutgoingMessage::Request(request),
                write_complete_tx: None,
            })
            .await
        {
            warn!("failed to resend request to client: {err:?}");
        }
    }

async fn take_connection_callback(
    &self,
    connection_id: ConnectionId,
    id: &RequestId,
) -> Option<(RequestId, PendingCallbackEntry)> {
    let mut callbacks = self.request_id_to_callback.lock().await;
    let entry = callbacks.get(id)?;
    if let Some(owner) = entry.verification_owner {
        if owner != connection_id {
            return None;
        }
        if entry.verification_identity != self.verification_identity()
            || entry.verification_auth_revision != self.verification_auth_revision()
        {
            callbacks.remove(id);
            return None;
        }
    }
    callbacks.remove_entry(id)
}

pub(crate) async fn pending_requests_for_thread(
    &self,
    thread_id: ThreadId,
) -> Vec<ServerRequest> {
    let request_id_to_callback = self.request_id_to_callback.lock().await;
    let mut requests = request_id_to_callback
        .values()
        .filter_map(|entry| {
            (entry.thread_id == Some(thread_id) && entry.verification_owner.is_none())
                .then_some(entry.request.clone())
        })
        .collect::<Vec<_>>();
    requests.sort_by(|left, right| left.id().cmp(right.id()));
    requests

